#include <map>
#include <iostream>

int main() {
    std::map<int, std::string> m = {{1, "One"}, {2, "Two"}};

    // O(log N) lookup, O(1) access via iterator
    auto it = m.find(1);
    if (it != m.end()) {
        std::cout << "Found: " << it->second << "\n";
    }

    // Access using operator[] (lookup + potential insertion)
    std::cout << "Access 2: " << m[2] << "\n";

    // m[10]; // Inserts {10, ""}

    // std::multimap<int, int> mm;
    // mm[1] = 1; // ERROR: multimap does not support operator[]
}
